// Range Sum of BST (Pruned Recursive search)
let tree = AnimatedBinaryTree<Int>()
tree.insert(10)
tree.insert(5)
tree.insert(15)
tree.insert(3)
tree.insert(7)
tree.insert(18)

let low = 7
let high = 15

let leftChild = [10: 5, 5: 3, 15: -1]
let rightChild = [10: 15, 5: 7, 15: 18]

func rangeSumBST(root: Int, low: Int, high: Int, t: AnimatedBinaryTree<Int>) -> Int {
    if root == -1 { return 0 }

    t.search(root)
    var sum = 0
    if root >= low && root <= high {
        sum += root
    }

    if root > low {
        if let left = leftChild[root] {
            sum += rangeSumBST(root: left, low: low, high: high, t: t)
        }
    }
    if root < high {
        if let right = rightChild[root] {
            sum += rangeSumBST(root: right, low: low, high: high, t: t)
        }
    }
    return sum
}

let sumVal = rangeSumBST(root: 10, low: low, high: high, t: tree)
